let is_continuation_byte c = Char.code c land 0b1100_0000 = 0b1000_0000

(* Skip leading continuation bytes in [s.[start .. end_)]: the tail of a
   multi-byte sequence whose lead byte falls before [start]. *)
let skip_leading_continuations s ~start ~end_ =
  let i = ref start in
  while !i < end_ && is_continuation_byte s.[!i] do
    incr i
  done;
  !i

let safe_range s ~start ~end_ =
  let start' = skip_leading_continuations s ~start ~end_ in
  let end' =
    let i = ref start' in
    let last_ok = ref start' in
    (try
       while !i < end_ do
         let d = String.get_utf_8_uchar s !i in
         let len = Uchar.utf_decode_length d in
         (* [len] bytes starting at [i] exist in [s] (that's how
            [get_utf_8_uchar] computed it), but they may run past
            [end_], which is what we actually care about here --
            regardless of whether the sequence is itself well-formed. *)
         if !i + len > end_ then raise Exit
         else begin
           i := !i + len;
           last_ok := !i
         end
       done
     with
    | Exit -> ());
    !last_ok
  in
  (start', end')

